-- 0004_appstore_timestamps_timestamptz.up.sql
-- Convert module timestamp columns from TEXT to TIMESTAMPTZ.
-- Appstore tables historically stored ISO-8601 timestamps as TEXT; row structs
-- decode them as chrono DateTime<Utc>, which sqlx only accepts from
-- TIMESTAMPTZ columns on PostgreSQL. ISO text values convert losslessly.

ALTER TABLE appstore_app ALTER COLUMN approved_at TYPE TIMESTAMPTZ USING approved_at::timestamptz;
